CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.license_verification_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_jwk jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.license_verification_keys TO anon, authenticated;
GRANT ALL ON public.license_verification_keys TO service_role;
ALTER TABLE public.license_verification_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_verification_read ON public.license_verification_keys FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.license_signing_keys (key_id uuid PRIMARY KEY REFERENCES public.license_verification_keys(id), encrypted_private_key text NOT NULL, encryption_iv text NOT NULL);
GRANT ALL ON public.license_signing_keys TO service_role;
ALTER TABLE public.license_signing_keys ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.device_licenses (id uuid PRIMARY KEY, device_id text NOT NULL UNIQUE, issued_by uuid NOT NULL, key_id uuid NOT NULL REFERENCES public.license_verification_keys(id), payload jsonb NOT NULL, activation_code text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.device_licenses TO authenticated;
GRANT ALL ON public.device_licenses TO service_role;
ALTER TABLE public.device_licenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_license_read ON public.device_licenses FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));